  /** Width point. Params: {action?: add|set|remove, index?, t? (0-1 along the path), width? (px) | scale? (? stroke weight)} ? add needs t (width defaults to the current one); set moves or resizes point `index`; with `side` only that side of the path changes (looking along it): `width` is then the distance from the centre line to that edge and `scale` that side's scale (? stroke weight, as if both sides were that wide). Changes the document. */
  "vector.edit.widthPoint": { action?: "add" | "set" | "remove"; /** a position counted from 0 (the first is 0) */ index?: number }
  /** Shape builder regions. Params: {ids?} ? {sources (bottom to top), regions: [{index, path (SVG, page), sources (top-most first), parts: [{id, stroke}] (the fills and outlined strokes covering it, top-most first), bounds [x, y, w, h], point [x, y] inside}]} ? visible strokes take part as their outlined areas, so stroked lines and open paths split regions */
  "shapeBuilder.regions": { ids?: Array<number> }
  /** Merge regions. Params: {ids?, regions?: [i, ...], points?: [[x, y], ...] (page)} ? {id, changed, removed, outlines, regions} ? one new shape from the regions, styled like the top-most fill or stroke over the first; the shapes lose those areas (strokes of the shapes involved become outlined vectors: `outlines`). Changes the document. */
  "shapeBuilder.merge": { ids?: Array<number>; /** page */ points?: Array<Array<number>>; /** [i] */ regions?: Array<number> }
  /** Remove regions. Params: {ids?, regions?: [i, ...], points?: [[x, y], ...] (page)} ? {changed, removed, outlines, regions} ? the shapes (and strokes) covering the regions lose them. Changes the document. */
  "shapeBuilder.remove": { ids?: Array<number>; /** page */ points?: Array<Array<number>>; /** [i] */ regions?: Array<number> }
  /** Shape builder mode. Params: {mode: merge|remove} (what a click does; Alt does the other) */
  "shapeBuilder.mode": { mode?: "merge" | "remove" }
  /** Code for layer. Params: {id?, language?: css|html|react|leptos|vue|tailwind|swiftui|compose|arkui (default css; html, react, leptos and vue are the whole layer tree; components take their properties as parameters, instances pass their values; a component connected to code (codeConnect.set) gives its import and snippet instead; tailwind is React with Tailwind CSS v4 utilities for pages: fluid auto layout boxes, instances inlined with their overrides, bound variables as theme utilities), mobile? (tailwind: a mobile frame with the same layer names; the code is mobile first with the desktop layer's classes behind lg:), unit?: px|rem (CSS, HTML, React, Leptos and Vue; default px), rootFontSize? (rem: pixels per rem, default 16)} ? {code, language, connected} */
  "inspect.code": { id?: number; /** default css; html, react, leptos and vue are the whole layer tree; components take their properties as parameters, instances pass their values; a component connected to code (codeConnect.set) gives its import and snippet instead; tailwind is React with Tailwind CSS v4 utilities for pages: fluid auto layout boxes, instances inlined with their overrides, bound variables as theme utilities */ language?: "css" | "html" | "react" | "leptos" | "vue" | "tailwind" | "swiftui" | "compose" | "arkui"; /** px|rem (CSS, HTML, React, Leptos and Vue; default px); CSS, HTML, React, Leptos and Vue; default px */ unit?: Json }
  /** Ready for dev. Params: {status?: readyForDev|changed|completed|any (default readyForDev; changed: ready for dev and changed since marked), page? (page id; default every page)} ? {items: [{id, name, page, status, changed}]}  frames and sections by handoff status (set it with `node.set {devStatus}`) */
  "inspect.readyForDev": { /** readyForDev|changed|completed|any (default readyForDev; changed: ready for dev and changed since marked); default readyForDev; changed: ready for dev and changed since marked */ status?: Json }
  /** Inspect assets. Params: {ids? (default the selection)} ? {assets: [{id, name, kind: export|icon|image, exports}]}  the layers in and under them to hand over as files: those with export settings, icons (small, vector shapes only; SVG) and images (PNG). Export them with `file.exportLayers {assets: true}` */
  "inspect.assets": Record<string, never>
  /** Inspect properties. Params: {id?, colorFormat?: hex|rgb|css|hsl|hsb (default hex)} ? {sections: [{title, rows: [{label, value, color?, token?}]}]}  layout (positions from the frame around the layer), auto layout, typography, fills, strokes and effects, with style and variable names */
  "inspect.properties": { /** hex|rgb|css|hsl|hsb (default hex); default hex */ colorFormat?: Json; id?: number }
  /** Component code. Params: {id? (component, set or instance; default the selection), language?: react|leptos|vue|swiftui|compose|arkui (default react)} ? {component, name, set, properties: [{name, param, type, default, value? (instances)}], definition, usage? (instances; the connected snippet when the component is connected to code), connected: {importPath, name, template, import, code} | null} */
  "inspect.componentCode": { /** default react */ language?: "react" | "leptos" | "vue" | "swiftui" | "compose" | "arkui" }
  /** Component playground. Params: {id? (an instance, a component or a component set; default the selection), properties? {name: value} (variant, boolean, text and instance-swap properties, as instance.setProperties takes them), language? css|html|react|leptos|vue|swiftui|compose|arkui (default react), path? (write the preview there as a PNG), scale? (the PNG's, default 2)} ? {component, properties: [{name, type, options?, value}], language, code, width, height, path?}  the component with those property values, tried on a copy: its code and its look. Nothing in the document changes */
  "component.playground": Record<string, never>
  /** Connect to code. Params: {id? (component, set or instance; default the selection), language?: react|leptos|vue|swiftui|compose|arkui (default react), importPath?, name? (default the generated name), template? (default a call passing every property)}  links the component (its set, for a variant) to its code component; fields left out keep their current value. Placeholders: {property} (its name or parameter name) and {property ? "a" : "b"}; other {...} stay as written  ? {component, language, code (the snippet for the layer), unknown (placeholder names that aren't properties)}. Changes the document. */
