  "codeConnect.export": Record<string, never>
  /** Import code connections. Params: {json (the connect JSON as codeConnect.export writes it: an object or JSON text) | path (a kition-fig.connect.json)}  links each entry to every component or set of that name (replacing its link for the language); invalid entries and unknown components are skipped with a warning  ? {linked, warnings}. Changes the document. */
  "codeConnect.import": Record<string, never>
  /** Add annotation. Params: {id? (default the first selected layer), label? (the note), properties?: [width|height|top|left|rotation|opacity|cornerRadius|direction|gap|padding|alignment|fontFamily|fontStyle|fontSize|lineHeight|letterSpacing|textAlign|fill|stroke|strokeWeight|effects], category? (id or name)} ? {id, index}  (a note, pinned properties or both). Changes the document. */
  "annotation.add": { properties?: Array<"width" | "height" | "top" | "left" | "rotation" | "opacity" | "cornerRadius" | "direction" | "gap" | "padding" | "alignment" | "fontFamily" | "fontStyle" | "fontSize" | "lineHeight" | "letterSpacing" | "textAlign" | "fill" | "stroke" | "strokeWeight" | "effects"> }
  /** Edit annotation. Params: {id?, index, label?, properties?: [..] (replaces the pinned properties), category? (id or name; null: none)}. Changes the document. */
  "annotation.edit": { id?: number; /** a position counted from 0 (the first is 0) */ index?: number; label?: string; /** [..] (replaces the pinned properties); replaces the pinned properties */ properties?: Array<Json> }
  /** Remove annotation. Params: {id?, index? (omit: every annotation on the layer)}. Changes the document. */
  "annotation.remove": { id?: number }
  /** List annotations. Params: {ids? | id? (those layers), page? (page id, or "all"; default the current page), category? (id or name, or "none": only those)} ? {annotations: [{id, name, index, label, category?: {id, name, color}, properties: [{property, label, value (null when the layer has none), token?, color?}]}]} */
  "annotation.list": Record<string, never>
  /** Annotation categories. Params: {} ? {categories: [{id, name, color, count (annotations in it, every page)}]} */
  "annotation.categories": Record<string, never>
  /** Add annotation category. Params: {name, color? (default the first unused colour)} ? {id}. Changes the document. */
  "annotation.addCategory": { name?: string }
  /** Edit annotation category. Params: {id (id or name), name?, color?}  (rename and/or recolour). Changes the document. */
  "annotation.editCategory": { color?: string; name?: string }
  /** Delete annotation category. Params: {id (id or name)} ? {id, uncategorized (how many annotations were in it)}  (its annotations stay, without a category). Changes the document. */
  "annotation.removeCategory": Record<string, never>
  /** Add dev resource. Params: {id? (default the first selected layer), url (http or https), name? (default the URL without its scheme)}  a link for developers on the layer; an instance also shows its main component's ? {id, index}. Changes the document. */
  "devResource.add": Record<string, never>
  /** Edit dev resource. Params: {id?, index (of the layer's own), url?, name?}  ? {id, index}. Changes the document. */
  "devResource.edit": { id?: number; name?: string; url?: string }
  /** Remove dev resource. Params: {id?, index? (omit: every dev resource of the layer's own)}  ? {removed}. Changes the document. */
  "devResource.remove": { id?: number }
  /** List dev resources. Params: {id? (default the first selected layer)}  the layer's links, its own first, then inherited from its main component and that component's set ? [{name, url, index? (own), from? (the layer it comes from)}] */
  "devResource.list": Record<string, never>
  /** Add measurement. Params: {from? (default the first selected layer), to? (a layer on the same page), side? (top|right|bottom|left)}  keeps a measurement on the canvas: between `from` and `to`, across one side of `from`, or (neither) to the layer around it; Dev Mode draws it and it follows the layers ? {from, index, lines}. Changes the document. */
  "devMode.addMeasurement": Record<string, never>
  /** Remove measurement. Params: {from? (default the first selected layer), index? (omit: every measurement starting from the layer)}  ? {removed}. Changes the document. */
  "devMode.removeMeasurement": Record<string, never>
  /** List measurements. Params: {page? (default the current page), id? (only those from or to this layer)}  ? [{from, fromName, index, to?, toName?, side?, labels, lines: [{x0, y0, x1, y1, label, dashed}]}] (page space) */
  "devMode.measurements": Record<string, never>
  /** Measure distances. Params: {ids? (default selection), to? (layer id; default the parent)} ? {lines: [{x0, y0, x1, y1, label, dashed}]} (page space; what Alt-hover shows) */
  "measure.distances": Record<string, never>
  /** Measure auto layout padding. Params: {id? (an auto layout frame or a child; default the selection)} ? {frame, lines} (padding and gaps; what Shift+Alt-hover shows) */
  "measure.padding": Record<string, never>
  /** List branches. Params: {}  the branches of the file shown (or of the file a branch tab belongs to), oldest first ? [{id, name, time (Unix seconds), state: active|merged|archived, index? (its open tab)}] */
  "branch.list": Record<string, never>
  /** Update from main. Params: {id?, resolutions? ({<conflict key>: "branch" | "main"})}  bring the main file's changes since the branch was made into the branch (a version in its history); refused while a conflict has no resolution. Not undoable (the branch tab's undo history starts over) ? {updated, changes, conflicts}. Changes the document. */
