  /** Archive branch. Params: {id?}  set the branch aside without merging (it stays in the file and can still be opened) and close its tab. Changes the document. */
  "branch.archive": { id?: number }
  /** Insert widget. Params: {plugin (a widget plugin's id), x?, y? (top-left; default: centred in the view), fuel?} the plugin draws it; one undo step ? {id, plugin, state, targets, output, logs, calls, fuel}. Changes the document. */
  "widget.insert": { /** fuel (no type given) */ fuel?: Json; x?: number }
  /** Click widget. Params: {id (a widget or a layer in one), target (see widget.list), fuel?} calls the widget's plugin back, which redraws it; one undo step ? like widget.insert. Changes the document. */
  "widget.click": { /** fuel (no type given) */ fuel?: Json }
