  "widget.setText": { /** fuel (no type given) */ fuel?: Json }
  /** Widget menu. Params: {id (a widget or a layer in one), item (see widget.list), value? (a toggle: on or off, default the opposite of now; a colour: one of its options), fuel?} picks an item of the widget's property menu: the plugin is called back; one undo step ? like widget.insert. Changes the document. */
  "widget.menu": { /** fuel (no type given) */ fuel?: Json }
  /** List widgets. Params: {} ? {widgets: [{id, plugin, name, page, state, targets, fields, menu}]} */
  "widget.list": Record<string, never>
